import java.util.Scanner;

public class Main {
    public static int computeGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int limit = sc.nextInt();

        int divisor = computeGCD(a, b);
        a /= divisor;
        b /= divisor;

        if (limit >= b) {
            System.out.println(a + "/" + b);
        } else {
            double ratio = (double) a / b;
            double minDiff = ratio;
            int bestNum = 0;
            int bestDen = 1;

            for (int i = 1; i <= limit; i++) {
                double val = i * ratio;
                double floorVal = Math.floor(val);
                double diff1 = Math.abs(floorVal / i - ratio);
                double diff2 = Math.abs((floorVal + 1) / i - ratio);

                if (minDiff > diff1 || minDiff > diff2) {
                    if (diff1 > diff2) {
                        bestNum = (int) (floorVal + 1);
                    } else {
                        bestNum = (int) floorVal;
                    }
                    bestDen = i;
                    minDiff = Math.min(diff1, diff2);
                }
            }
            System.out.println(bestNum + "/" + bestDen);
        }
        sc.close();
    }
}
